<?php
/** Proof: menu items, modifiers, menu engineering, categories (recipes.md "Proof"). */
require __DIR__ . '/lib.php';
$f = recipes_fixture();
[$jd, ] = sign_on(30); [$jb, ] = sign_on(28); [$ja, ] = sign_on(29);
$since = last_activity_id();

echo "1. Menu items — the list and the unmapped queue, create, map, no_depletion, duplicates, prices, archive\n";
ri_sql("INSERT INTO pos_sales (scope_id, source_id, external_id, business_date, closed_at, covers, subtotal) VALUES (101, :s, 'SMOKE-CHK-9', current_date - 1, now() - interval '1 day', 2, 30)", ['s' => $f['source']]);
$sale = id_of("SELECT id FROM pos_sales WHERE external_id = 'SMOKE-CHK-9'");
ri_sql("INSERT INTO pos_sale_lines (sale_id, plu, name, qty, unit_price, line_total) VALUES (:s, '2002', 'SMOKE Mystery special', 3, 9.00, 27.00), (:s2, '1001', 'SMOKE Chicken Sandwich', 1, 14.00, 14.00)", ['s' => $sale, 's2' => $sale]);
$mystery = id_of("SELECT id FROM menu_items WHERE plu = '2002'");
$r = page($jd, '/menu/');
ok($r['code'] === 200 && has($r, 'id="menu-items-table"') && has($r, 'id="unmapped-band"') && has($r, 'id="unmapped-' . $mystery . '"') && has($r, 'id="menu-item-row-' . $f['plu1001'] . '"'), 'the list with the unmapped band naming the Mystery special sold yesterday');
ok(preg_match('/id="menu-item-row-' . $mystery . '"[^>]*class="table-warning"/', $r['body']) && has($r, 'id="menu-item-row-' . $mystery . '-map"'), 'the unmapped row is banded with a Map button');
$r = post_json($jd, '/menu/save.php', ['plu' => '3003', 'name' => 'SMOKE Service charge', 'sale_price' => 2.00]);
ok($r['code'] === 200 && $r['json']['ok'] && str_starts_with($r['json']['location'], '/menu/'), 'a typed menu item (no POS) is created');
$svc = (int) $r['json']['record_id'];
$r = post_json($jd, '/menu/save.php', ['plu' => '1001', 'name' => 'dup', 'source' => $f['source']]);
ok($r['code'] === 422 && str_contains($r['body'], 'already on the list'), 'a duplicate PLU on the source is refused in words');
$r = post_json($jd, '/menu/map.php', ['menu_item' => $mystery, 'recipe' => $f['stock']]);
ok($r['code'] === 422 && str_contains($r['body'], 'menu-item recipe'), 'a map to a prep is refused: "A menu item maps to a menu-item recipe"');
$r = post_json($jd, '/menu/map.php', ['menu_item' => $mystery, 'recipe' => $f['sandwich'], 'portions' => 1.5, 'price' => 16.00]);
ok($r['code'] === 200 && (int) one('SELECT recipe_id FROM menu_items WHERE id = :m', ['m' => $mystery]) === $f['sandwich'] && (int) one('SELECT mapped_by FROM menu_items WHERE id = :m', ['m' => $mystery]) === 30 && one('SELECT mapped_at FROM menu_items WHERE id = :m', ['m' => $mystery]) !== null, 'the Mystery special mapped to the sandwich at 1.5 portions — mapped_by/at stamped');
ok((float) one('SELECT ri_menu_price(:m, 101)', ['m' => $mystery]) === 16.0, 'and priced $16 at Downtown through the same POST');
$r = page($jd, '/menu/');
ok(!has($r, 'id="unmapped-band"'), 'the unmapped band is gone');
$r = post_json($jd, '/menu/map.php', ['menu_item' => $svc, 'no_depletion' => 'yes']);
ok($r['code'] === 200 && (bool) one('SELECT no_depletion FROM menu_items WHERE id = :m', ['m' => $svc]) && one('SELECT recipe_id FROM menu_items WHERE id = :m', ['m' => $svc]) === null, 'the service charge sells nothing from stock (db/018\'s column; the recipe cleared)');
ri_sql("INSERT INTO pos_sale_lines (sale_id, plu, name, qty, unit_price, line_total) VALUES (:s, '3003', 'SMOKE Service charge', 1, 2.00, 2.00)", ['s' => $sale]);
ok((int) one('SELECT count(*) FROM ri_unmapped_plus(101) WHERE menu_item_id = :m', ['m' => $svc]) === 0, 'and it stays out of the unmapped queue although it sold');
$r = post_json($jd, '/menu/map.php', ['menu_item' => '2002', 'recipe' => '']);
ok($r['code'] === 200 && one('SELECT recipe_id FROM menu_items WHERE id = :m', ['m' => $mystery]) === null, 'a blank recipe unmaps (the menu item named by its PLU)');
post_json($jd, '/menu/map.php', ['menu_item' => $mystery, 'recipe' => $f['sandwich']]);
$r = post_json($jd, '/menu/price.php', ['menu_item' => $f['plu1001'], 'price' => 15.50, 'site' => 101]);
ok($r['code'] === 200 && (float) one('SELECT ri_menu_price(:m, 101)', ['m' => $f['plu1001']]) === 15.5 && (float) one('SELECT ri_menu_price(:m, 102)', ['m' => $f['plu1001']]) === 14.0, 'a price of $15.50 at Downtown: ri_menu_price answers it there and the sale_price at Airport');
$r = post_json($jd, '/menu/price.php', ['menu_item' => $f['plu1001'], 'price' => 14.50, 'site' => '']);
ok($r['code'] === 200 && (float) one('SELECT sale_price FROM menu_items WHERE id = :m', ['m' => $f['plu1001']]) === 14.5 && (float) one('SELECT ri_menu_price(:m, 101)', ['m' => $f['plu1001']]) === 15.5, 'a price with no site sets the default; Downtown keeps its own');
$r = page($jd, '/menu/' . $f['plu1001']);
ok($r['code'] === 200 && has($r, 'id="menu-item-prices"') && has($r, 'id="menu-item-cost-plate"') && has($r, 'id="menu-item-modifiers"') && has($r, 'id="menu-item-sales"') && has($r, 'data-entity="menu_item"'), "the menu item's page: prices, the cost (Dana), modifiers, sales");
$r = page($jb, '/menu/' . $f['plu1001']);
ok($r['code'] === 200 && !has($r, 'id="menu-item-cost-plate"') && has($r, 'Cost withheld'), 'Bea: the cost card says withheld');
$r = post_json($jd, '/menu/archive.php', ['menu_item' => $svc]);
ok($r['code'] === 200 && !(bool) one('SELECT active FROM menu_items WHERE id = :m', ['m' => $svc]), 'archived');
ok(count(activity('menu_item.map', $since)) >= 4 && count(activity('menu_item.price_set', $since)) === 3 && count(activity('menu_item.archive', $since)) === 1 && count(activity('menu_item.create', $since)) === 1, 'menu_item.map|price_set|archive|create logged');
$a = activity('menu_item.map', $since);
ok(str_contains((string) $a[0]['after'], '"no_depletion"') && (int) $a[0]['recipe_id'] === $f['sandwich'], 'the map row carries no_depletion and recipe_id');

echo "2. Modifiers\n";
$r = page($jd, '/modifiers/');
ok($r['code'] === 200 && has($r, 'id="modifiers-table"') && has($r, 'id="modifier-row-' . $f['xchk'] . '"'), 'the modifiers list');
$r = post_json($jd, '/modifiers/map.php', ['modifier' => $f['xchk'], 'action' => 'add', 'recipe' => $f['modifier'], 'qty_factor' => 1]);
ok($r['code'] === 200 && one('SELECT action FROM modifiers WHERE id = :m', ['m' => $f['xchk']]) === 'add' && (int) one('SELECT recipe_id FROM modifiers WHERE id = :m', ['m' => $f['xchk']]) === $f['modifier'], 'XCHK mapped add to the Extra chicken recipe, factor 1');
$r = post_json($jd, '/modifiers/map.php', ['modifier' => 'XCHK', 'action' => 'add', 'recipe' => $f['sandwich']]);
ok($r['code'] === 422 && str_contains($r['body'], 'modifier recipe'), 'a map to a menu-item recipe is refused in words (the modifier named by its code)');
$r = post_json($jd, '/modifiers/map.php', ['modifier' => $f['xchk'], 'action' => 'remove', 'recipe' => '']);
ok($r['code'] === 422 && str_contains($r['body'], 'names its modifier recipe'), 'remove without a recipe is refused');
ri_sql("INSERT INTO modifiers (pos_source_id, code, name) VALUES (:s, 'NOTOM', 'SMOKE No tomato')", ['s' => $f['source']]);
$notom = id_of("SELECT id FROM modifiers WHERE code = 'NOTOM'");
$r = post_json($jd, '/modifiers/map.php', ['modifier' => $notom, 'action' => 'none']);
ok($r['code'] === 200 && one('SELECT action FROM modifiers WHERE id = :m', ['m' => $notom]) === 'none', 'none without a recipe is accepted');
$r = post_json($jd, '/modifiers/map.php', ['modifier' => $f['xchk'], 'menu_item' => $f['plu1001'], 'parent_recipe' => $f['modifier'], 'parent_qty_factor' => 2]);
ok($r['code'] === 200 && (float) one('SELECT qty_factor FROM menu_item_modifiers WHERE menu_item_id = :m AND modifier_id = :md', ['m' => $f['plu1001'], 'md' => $f['xchk']]) === 2.0, 'a per-item override for PLU 1001: factor 2');
$r = page($jd, '/modifiers/' . $f['xchk'] . '/map');
ok($r['code'] === 200 && has($r, 'id="modifier-form"') && has($r, 'id="per-item-table"') && has($r, 'id="per-item-row-' . $f['plu1001'] . '"'), 'the modifier form with the per-item row');
$a = activity('modifier.map', $since);
ok(count($a) === 3 && str_contains((string) end($a)['after'], '"menu_item_id"'), 'modifier.map logged three times, the per-item one with menu_item_id');
ok(page($jb, '/modifiers/')['code'] === 403, 'Bea (Kitchen) may not map modifiers');

echo "3. Menu engineering\n";
$r = page($jd, '/menu/engineering');
ok($r['code'] === 200 && has($r, 'id="engineering-empty"'), 'an empty window says so');
$salad = post_json($jd, '/recipes/save.php', ['name' => 'SMOKE Salad', 'kind' => 'menu_item', 'menu_category' => 'mains', 'lines' => json_encode([['ingredient' => $f['lettuce'], 'qty' => 80, 'unit' => 'g']])]);
post_json($jd, '/recipes/versions/activate.php', ['version' => (int) $salad['json']['version_id'], 'effective_from' => date('Y-m-d', strtotime('-30 days'))]);
ri_sql("INSERT INTO ingredient_site_settings (ingredient_id, scope_id, cost_override_per_base) VALUES (:i, 101, 0.002)", ['i' => $f['lettuce']]);
$s1002 = post_json($jd, '/menu/save.php', ['plu' => '1002', 'name' => 'SMOKE Salad', 'source' => $f['source'], 'menu_category' => 'mains', 'sale_price' => 6.00, 'recipe' => (int) $salad['json']['record_id']]);
$saladItem = (int) $s1002['json']['record_id'];
for ($k = 1; $k <= 28; $k++) {
    $d = date('Y-m-d', strtotime("-{$k} days")); $dow = (int) date('N', strtotime($d));
    ri_sql('INSERT INTO sales_daily (scope_id, menu_item_id, business_date, day_part_id, qty, net) VALUES (101, :m, :d, NULL, :q, :n)', ['m' => $f['plu1001'], 'd' => $d, 'q' => in_array($dow, [5, 6], true) ? 40 : 20, 'n' => (in_array($dow, [5, 6], true) ? 40 : 20) * 14]);
    ri_sql('INSERT INTO sales_daily (scope_id, menu_item_id, business_date, day_part_id, qty, net) VALUES (101, :m, :d, NULL, 5, 30)', ['m' => $saladItem, 'd' => $d]);
}
$r = page($jd, '/menu/engineering');
ok($r['code'] === 200 && has($r, 'id="engineering-table"') && has($r, 'id="engineering-row-' . $f['plu1001'] . '"') && has($r, 'id="engineering-row-' . $saladItem . '"'), 'the table shows the sandwich and the salad');
ok(has($r, 'id="engineering-chart"') && has($r, 'id="engineering-point-' . $f['plu1001'] . '"') && has($r, 'id="engineering-point-' . $saladItem . '"'), 'the scatter with two markers');
ok(preg_match('/engineering-row-' . $f['plu1001'] . '".*?(Star|Plowhorse)/s', $r['body']) && preg_match('/engineering-row-' . $saladItem . '".*?(Dog|Puzzle)/s', $r['body']), 'the sandwich a star or plowhorse, the salad a dog or puzzle');
ok(preg_match('/CM average \$[0-9.]+, popularity threshold ([0-9.]+) %/', $r['body'], $m) && near((float) $m[1], 35, 0.1), "the category's CM average and the 70 % threshold (35 % for two items)");
$r = req('GET', '/menu/engineering', ['jar' => $jd, 'headers' => ['Accept: application/json']]);
$j = json_decode($r['body'], true);
ok($r['code'] === 200 && count($j['data']['groups'][0]['rows'] ?? []) === 2, 'as JSON: one category, two rows');
ok(page($ja, '/menu/engineering')['code'] === 403, 'Ann: 403');

echo "4. Categories\n";
$r = page($jd, '/menu/categories');
ok($r['code'] === 200 && preg_match_all('/id="menu-category-row-\d+"/', $r['body']) === 10, 'ten seeded categories, each an inline row form');
$r = post_json($jd, '/menu/categories/save.php', ['name' => 'SMOKE Specials', 'kind' => 'food']);
ok($r['code'] === 200 && one('SELECT key FROM menu_categories WHERE name = :n', ['n' => 'SMOKE Specials']) === 'smoke_specials', 'added with the key from the name');
$cid = (int) $r['json']['record_id'];
$r = req('POST', '/menu/categories/save.php', ['jar' => $jd, 'headers' => ['HX-Request: true'], 'form' => ['csrf_token' => page_csrf($jd), 'menu_category' => $cid, 'name' => 'SMOKE Daily specials']]);
ok($r['code'] === 200 && has($r, 'id="menu-category-row-' . $cid . '"') && one('SELECT name FROM menu_categories WHERE id = :id', ['id' => $cid]) === 'SMOKE Daily specials', 'renamed inline (Pattern C answers the row)');
$r = post_json($jd, '/menu/categories/save.php', ['name' => 'Dup', 'key' => 'mains']);
ok($r['code'] === 422 && str_contains($r['body'], 'already taken'), 'a duplicate key is refused');
ok(page($jb, '/menu/categories')['code'] === 403 && post_json($jb, '/menu/categories/save.php', ['name' => 'x'])['code'] === 403, 'Bea: 403 on the screen and the action');
ok(count(activity('menu_category.save', $since)) === 2, 'menu_category.save logged twice');
finish();
